cd /workspace
time timeout 300 duckdb work.duckdb -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;
CREATE OR REPLACE TABLE field_max_single AS
WITH ranked AS (
  SELECT field_id, cod_imovel, frac,
    max(frac) OVER (PARTITION BY field_id) as max_frac
  FROM single_test
),
within_tol AS (
  SELECT * FROM ranked WHERE frac >= max_frac - 1e-9
),
picked AS (
  SELECT field_id, max_frac,
    min(cod_imovel) as primary_cod_imovel
  FROM within_tol
  GROUP BY field_id, max_frac
)
SELECT * FROM picked;
SELECT count(*) FROM field_max_single;
"

