LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;
CREATE OR REPLACE TABLE field_aggregate AS
SELECT f.\"Id\" as field_id,
  ST_Area(ST_Intersection(f.geometry, b.geom)) / ST_Area(f.geometry) as agg_frac
FROM candidate_fields f, buffered_union b
WHERE ST_Intersects(f.geometry, b.geom);
SELECT count(*) FROM field_aggregate;
"

