LOAD spatial; LOAD httpfs;
CREATE OR REPLACE TABLE flagged_parcels AS
SELECT DISTINCT fe.primary_cod_imovel as cod_imovel
FROM field_eval fe JOIN scope_map sm ON fe.mbmode24=sm.mbmode24
WHERE fe.matched AND sm.in_scope AND fe.deforestarea2124 > 0;
