"

cd /workspace
timeout 60 duckdb work.duckdb -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;
CREATE OR REPLACE TABLE parcel_class_area AS
SELECT primary_cod_imovel as cod_imovel, mbmode24::INTEGER as mbmode24,
  sum(ST_Area_Spheroid(geometry))/10000 as ha
FROM field_eval WHERE matched
GROUP BY primary_cod_imovel, mbmode24;

CREATE OR REPLACE TABLE parcel_dominant AS
WITH ranked AS (
  SELECT *, row_number() OVER (PARTITION BY cod_imovel ORDER BY ha DESC, mbmode24 ASC) as rn
  FROM parcel_class_area
)
SELECT cod_imovel, mbmode24 as dominant_mb, ha FROM ranked WHERE rn=1;
SELECT count(*) FROM parcel_dominant;
"

